/* Mortes syntaxis in TEXTUM - UNA SEDES FORMAE (silva-migratio
 * T19b-1): examen, legati, briar hanc vocant. Humanus: 'via:linea:
 * columna: [violatio] causa' + excerptum ('hic coepit' / 'hic
 * exspectatur'); machina (non-zephyrum): TSV examinis. Mors sine
 * loco -> summarium 'nodi erroris (syntaxis) N'. fons/mensura =
 * textus fontis principalis (excerpta). mappatio NULL = identitas;
 * lineae ordinum ET excerpti mappantur (briar: textus silvae ->
 * linea .thistle). *linea_prima (NULL licet) = linea mappata
 * mortis locatae primae (0 si nulla). Plagula sine errore ->
 * chorda vacua. */
typedef unsigned int (*SilvaLineaMappatio)(void* datum,
                                           unsigned int linea);
SilvaChorda
silva_mortes_scribere (
               SilvaPiscina* piscina,
                 const char* via,
          const SilvaParsura* parsura,
    const SilvaRegistrumCoctum* tabularium,
                 const char* fons,
                unsigned int  mensura,
                         int  machina,
          SilvaLineaMappatio  mappatio,
                       void* datum,
                unsigned int* linea_prima);


/* ==================================================
 * Expansio: reading windows (additiones II) - SilvaExpansio stays
 * OPAQUE; these slim vistas are the cathedral-time contract
 * (internal shapes remain free). Ramus index = conditio_id - 1
 * (flat table). Extents are BYTE offsets into the fons text.
 * ================================================== */

typedef enum {
    SILVA_RAMUS_IF = 0,
    SILVA_RAMUS_IFDEF,
    SILVA_RAMUS_IFNDEF,
    SILVA_RAMUS_ELIF,
    SILVA_RAMUS_ELSE
} SilvaRamusGenus;

typedef struct {
    const SilvaChorda* via;
                  int  fons_ex;
                  int  fons_ad;           /* -1 = unresolved */
                  int  est_praetermissa;
                  int  est_angulata;      /* angle form vs quoted */
} SilvaInclusioVista;

typedef struct {
    SilvaRamusGenus genus;
                int est_sumptum;
                int est_numquam;       /* #if 0 idiom */
                int corpus_initium;    /* BYTES in fons; -1 empty */
                int corpus_finis;      /* exclusive; -1 empty */
                int fons_index;
       unsigned int linea;
} SilvaRamusVista;

typedef struct {
    const SilvaChorda* titulus;
                  int  est_functio;
                  int  fons_index;
         unsigned int  linea;
                  int  corpus_initium;  /* BYTES in fons (first body
                                         * token); -1 = empty/api */
    int corpus_finis;    /* exclusive; -1 = empty */
} SilvaMacroVista;

