/* ==================================================
 * Typatio expressionum (M0b) - tabula parallela nodus ->
 * {typus naturalis, typus conversus}: naturalis = typus proprius
 * SINE lapsu (acies manet acies - sizeof rectum); conversus =
 * conversio scopo applicata (lapsus/UAC/assignatio/argumentum/
 * reditus) aut NIHIL. Quaestiones canonicae-consciae (involucrum
 * ambiguum aut lectionem des, idem redditur). NB typatio RELATIVA
 * CANONICAE est: post recanonicare analysim NOVAM fac (percursus
 * bis analysat). Contractus demissionis officinae.
 * ================================================== */

const TypusC89*
silva_c89_typus_expressionis (
    const SilvaSemantica* sem,
        const SilvaNodus* nodus);
/* NIHIL = nulla conversio scopo applicata */
const TypusC89*
silva_c89_conversio_expressionis (
    const SilvaSemantica* sem,
        const SilvaNodus* nodus);
unsigned int
silva_c89_typationes_numerus (
    const SilvaSemantica* sem);

/* Redditor typorum (LEGATUS chunk 0): typus -> textus latinus
 * C-stili in buffer datum (NUL appenso). Functiones = signatura
 * "reditus(parametra)"; acies = "T[n]" / "T[]"; aggregata anonyma
 * = "<anonyma>" (typedef tag anonymum baptizat titulo suo). Redde
 * octetos scriptos; 0 = irreddibilis (error / spatium deficiens)
 * - buffer tunc vacuus. */
unsigned int
silva_c89_typum_scribere (
    const TypusC89* t,
              char* buffer,
      unsigned int  capacitas);


