/* ==================================================
 * Annotationes STML (stratum identitatis et intentionis)
 *
 * Commentarium cuius contentum primum non-spatium tag STML apertum
 * est ANNOTATIO est - collectum, purgatum (decoratio ' * ' exuta),
 * per stml_legere parsatum, unitati supremae affixum. Ancoratum
 * quod parsare nequit in fructu MANET (parsata falsum + positiones)
 * - numquam tacite prosa. Subcopia stml LEGENDI hic exposita;
 * scriptio/mutatio stml intra silva.c manent.
 * ================================================== */

/* internamentum praenuntiatum (opacum; creare + tradere) */
typedef struct SilvaInternamentumChorda SilvaInternamentumChorda;

SilvaInternamentumChorda*
silva_internamentum_creare (
    SilvaPiscina* piscina);

typedef enum {
    STML_NODUS_DOCUMENTUM   = 1,
    STML_NODUS_ELEMENTUM    = 2,
    STML_NODUS_TEXTUS       = 3,
    STML_NODUS_COMMENTUM    = 4,
    STML_NODUS_PROCESSIO    = 5,
    STML_NODUS_DOCTYPE      = 6,
    STML_NODUS_TRANSCLUSIO  = 7
} SilvaStmlNodusGenus;

typedef enum {
    STML_CAPTIO_NIHIL       = 0,
    STML_CAPTIO_ANTE        = 1,
    STML_CAPTIO_RETRO       = 2,
    STML_CAPTIO_FARCIMEN    = 3
} SilvaStmlCaptioDirectio;

typedef enum {
    STML_SUCCESSUS                   = 0,
    STML_ERROR_MEMORIA               = 1,
    STML_ERROR_SYNTAXIS              = 2,
    STML_ERROR_TAG_NON_CLAUSUM       = 3,
    STML_ERROR_TAG_IMPROPRIE        = 4,
    STML_ERROR_ATTRIBUTUM            = 5,
    STML_ERROR_VACUUM_INPUT          = 6,
    STML_ERROR_CAPTIO                = 7,
    /* recusationes '<tag\>' (spec triviae §1.4) - causa in
     * result.error nominatur */
    STML_ERROR_MULTILINEA            = 8
} SilvaStmlStatus;

typedef struct {
    SilvaChorda* titulus;    /* internata */
    SilvaChorda* valor;      /* internata ("true" pro boolean) */
    SilvaChorda* spatia_ante; /* trivia intra tagum (§1.6): spatium
                               * ante attributum; NIHIL = unicum
                               * canonicum */
} SilvaStmlAttributum;

typedef struct SilvaStmlNodus {
    SilvaStmlNodusGenus  genus;
            SilvaChorda* titulus;     /* elementorum */
            SilvaChorda* valor;       /* textus/commenti/PI */
               SilvaXar* attributa;   /* SilvaStmlAttributum */
               SilvaXar* liberi;      /* SilvaStmlNodus* */
    struct SilvaStmlNodus*  parens;
    unsigned int linea;       /* linea fontis, 1-basata;
                                          * 0 = non e parsatione */
    unsigned int positus_initium; /* extensio octetorum
                                          * [initium, finis) in fonte
                                          * PARSATO: tag aperiens
                                          * usque post claudens; 0/0
                                          * si non e parsatione */
               unsigned int positus_finis;
                        int crudus;
    SilvaStmlCaptioDirectio captio_directio;
               unsigned int captio_numerus;
                        int clausura_anonyma; /* clausum per </> -
                                               * scriptor formam
                                               * authoris servat */
            int  fragmentum;
    SilvaChorda* fragmentum_id;
    SilvaChorda* augmentum_clavis; /* '<% &clavis;>' -
                                               * clavis VERBATIM
                                               * sigillata; NIHIL =
                                               * elementum
                                               * ordinarium */
    SilvaChorda* attributum_titulus; /* '<@titulus=>' -
                                               * elementum attributi
                                               * (par. 6.3): titulus
                                               * '@' geritur, nomen
                                               * attributi HIC;
                                               * NIHIL = elementum
                                               * ordinarium; vacuum
                                               * = sepulcrum */

    /* TRIVIA (spec triviae §1): valor est sensus, spatium album
     * dispositio iuxta eum lata. NIHIL = nullum. Lex possessoris
     * §1.2: cursus inter nodos per primam '\n' INCLUSIVE prioris
     * est (post), residuum sequentis (ante). Scriptor fidelis
     * verbatim reassuit. */
    SilvaChorda* spatia_ante;
    SilvaChorda* spatia_post;
    SilvaChorda* spatia_clausurae; /* interius ante tag
                                               * claudens; documento
                                               * cauda plagulae */
    SilvaChorda* spatia_intra_tagum; /* ante '>' (§1.6) */

    /* '<tag\>' (§1.4): lineae novae contentum, dedentatio in
     * parsatione, praefixum in 'indentatio' conditum */
            int  multilinea;
    SilvaChorda* indentatio;
} SilvaStmlNodus;

typedef struct {
                int  successus;
     SilvaStmlNodus* radix;
     SilvaStmlNodus* elementum_radix;
    SilvaStmlStatus  status;
       unsigned int  linea_erroris;
       unsigned int  columna_erroris;
        SilvaChorda  error;
                int  crlf_canonicalizatum; /* '\r\n' -> '\n' in
                                            * introitu factum (§3) */
} SilvaStmlResultus;

SilvaStmlResultus
silva_stml_legere (
                 SilvaChorda  input,
                SilvaPiscina* piscina,
    SilvaInternamentumChorda* intern);
