    nodus->positus_finis = ZEPHYRUM;
    nodus->spatia_ante = NIHIL;
    nodus->spatia_post = NIHIL;
    nodus->spatia_clausurae = NIHIL;
    nodus->spatia_intra_tagum = NIHIL;
    nodus->multilinea = FALSUM;
    nodus->indentatio = NIHIL;

